import { readFile } from "node:fs/promises";
import path from "node:path";

const TYPES: Record<string, string> = {
  jpg: "image/jpeg",
  png: "image/png",
  webp: "image/webp",
  avif: "image/avif",
};

/** Serves product photos uploaded from the admin panel (stored in data/uploads). */
export async function GET(_request: Request, { params }: RouteContext<"/uploads/[name]">) {
  const { name } = await params;
  // Names are generated by the upload action; anything else (including path traversal) is rejected.
  const match = /^[a-f0-9]{24}\.(jpg|png|webp|avif)$/.exec(name);
  if (!match) return new Response("Not found", { status: 404 });
  try {
    const file = await readFile(path.join(process.cwd(), "data", "uploads", name));
    return new Response(new Uint8Array(file), {
      headers: {
        "Content-Type": TYPES[match[1]],
        "Cache-Control": "public, max-age=31536000, immutable",
        "X-Content-Type-Options": "nosniff",
      },
    });
  } catch {
    return new Response("Not found", { status: 404 });
  }
}
